const ingredientAddPrices={cheese:1,pineapple:0.5,corn:0.5,mushroom:1};
const mandatoryIngredients=new Set(['lavash','meat']);
let cart=[],filter='all',serial=0;
const CART_KEY='schawa-grill-cart-v1';
function saveCart(){try{localStorage.setItem(CART_KEY,JSON.stringify(cart))}catch(err){console.warn('Warenkorb konnte nicht gespeichert werden',err)}}
function restoreCart(){try{const saved=JSON.parse(localStorage.getItem(CART_KEY)||'[]');if(!Array.isArray(saved))return;cart=saved.filter(x=>x&&products.some(p=>p.id===x.id)).slice(0,100).map(x=>{const p=products.find(p=>p.id===x.id.replace(/^combo-/,'menu-')),base=newLine(p);return {...base,uid:base.uid,drink:drinkChoices.some(d=>d[0]===x.drink)?x.drink:base.drink,ingredients:{...base.ingredients,...(x.ingredients&&typeof x.ingredients==='object'?x.ingredients:{})},extras:{...(x.extras&&typeof x.extras==='object'?x.extras:{})},halved:!!x.halved,note:typeof x.note==='string'?x.note.slice(0,220):''}});saveCart()}catch(err){console.warn('Warenkorb konnte nicht geladen werden',err)}}
const $=s=>document.querySelector(s), euro=n=>n.toLocaleString('de-DE',{style:'currency',currency:'EUR'}), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
products.push(...products.filter(p=>p.category==='shawarma').map(p=>({...p,id:'menu-'+p.id,name:p.name+' Menü',price:p.price+4,desc:p.name+' + Pommes + Getränk nach Wahl',image:({classic:'combo-classic.webp',xl:'combo-xl.webp'})[p.id]||p.image,category:'combos',shawarmaId:p.id})));
const isShawarma=p=>p.category==='shawarma'||p.category==='combos';
const drinkChoices=[['water','Mineralwasser'],['cola','Coca-Cola'],['sprite','Sprite']];
function toggleHomeCategory(cat){const target=document.querySelector('.home-category-panel[data-cat="'+cat+'"]');if(!target)return;const opening=target.hidden;document.querySelectorAll('.home-category-panel').forEach(x=>x.hidden=true);document.querySelectorAll('.home-category-toggle').forEach(x=>x.setAttribute('aria-expanded','false'));target.hidden=!opening;document.querySelector('.home-category-toggle[data-cat="'+cat+'"]')?.setAttribute('aria-expanded',String(opening));}
function go(page){const prior=lastOrder();syncActiveOrder();document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===page));$('#drawer').hidden=true;syncMenu();window.scrollTo(0,0);updateBottom();history.replaceState(null,'','#'+page);if(page==='orderHistory')sgHistory()}
function goPreorder(){go(activeOrder()||cart.length?'order':'menu')}
function setFilter(cat){filter=cat;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===cat));renderMenu()}
function ingredientsFor(p){return ingredients.filter(([id])=>{if(p.hawaii&&['tomato','pickle','cheese'].includes(id))return false;return !['cheese','pineapple','corn','mushroom'].includes(id)||((id==='cheese'&&p.defaultCheese)||(p.hawaii&&['pineapple','corn'].includes(id))||(p.mushroom&&id==='mushroom'))})}
function defaultIds(p){return new Set(ingredientsFor(p).map(([id])=>id))}
function eggFreeIcon(){return `<span class="eggfree-badge" title="Ohne Ei" aria-label="Ohne Ei"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3C8.8 3 6.4 8.5 6.4 13a5.6 5.6 0 0 0 11.2 0C17.6 8.5 15.2 3 12 3Z" fill="#fff1d4" stroke="#8e6749" stroke-width="1.7"/><circle cx="12" cy="12.5" r="3" fill="#f2b93b"/><path d="M4 20 20 4" stroke="#db182c" stroke-width="3.5" stroke-linecap="round"/></svg></span>`}
function ingredientsHtml(line,editable,product){
 const p=product||(line&&products.find(x=>x.id===line.id))||products[0];
 const defaults=defaultIds(p);
 const shown=editable?ingredients.filter(([id])=>defaults.has(id)):ingredientsFor(p);
 return `<div class="ingredients ${editable?'editable':''}">${shown.map(([id,icon,label])=>{
  const mandatory=mandatoryIngredients.has(id);
  const defaultIncluded=defaults.has(id);
  const enabled=mandatory||(line?(line.ingredients[id]===true):defaultIncluded);
  const extraCost=!defaultIncluded&&!mandatory?(ingredientAddPrices[id]||0):0;
  const priceLabel=editable&&!defaultIncluded?`<span class="ingredient-price">${extraCost?'+'+euro(extraCost):'Gratis'}</span>`:'';
  const optionalLabel=editable&&!defaultIncluded?'<span class="ingredient-optional">Extra</span>':'';
  return editable?`<label class="ingredient ingredient-toggle ${id==='sauce'?'ingredient-sauce-item':''} ${enabled?'':'removed'} ${mandatory?'mandatory':''} ${!defaultIncluded?'ingredient-addable':''}" ${mandatory?'title="Pflichtzutat – immer enthalten"':''}><input type="checkbox" data-ingredient="${id}" data-line="${line.uid}" ${enabled?'checked':''} ${mandatory||(missingStock(id)&&!enabled)?'disabled':''}><img class="ingredient-photo" src="assets/${icon}" alt="" loading="lazy">${id==='sauce'?eggFreeIcon():''}<span class="ingredient-label">${label}</span>${optionalLabel}${priceLabel}${mandatory?'<span class="ingredient-lock" aria-label="Pflichtzutat">🔒</span>':''}</label>`:`<span class="ingredient ${id==='sauce'?'ingredient-sauce-item':''}"><img class="ingredient-photo" src="assets/${icon}" alt="" loading="lazy">${id==='sauce'?eggFreeIcon():''}<span class="ingredient-label">${label}</span>${mandatory?'<span class="ingredient-lock" aria-label="Pflichtzutat">🔒</span>':''}</span>`
 }).join('')}</div>`
}
function extrasHtml(line){
 const p=products.find(x=>x.id===line.id), defaults=defaultIds(p);
 const optional=ingredients.filter(([id])=>['cheese','pineapple','corn','mushroom'].includes(id)&&!defaults.has(id));
 const baseExtras=extras.map(([id,label,price])=>`<label class="extra-row"><input type="checkbox" data-extra="${id}" data-line="${line.uid}" ${line.extras[id]?'checked':''} ${missingStock(id)&&!line.extras[id]?'disabled':''}><span>${label}</span><small>${price===0?'Kostenlos':'+'+euro(price)}</small></label>`);
 const ingredientExtras=optional.map(([id,,label])=>`<label class="extra-row"><input type="checkbox" data-ingredient="${id}" data-line="${line.uid}" ${line.ingredients[id]?'checked':''} ${missingStock(id)&&!line.ingredients[id]?'disabled':''}><span>${label}</span><small>+${euro(ingredientAddPrices[id]||0)}</small></label>`);
 const all=[...baseExtras,...ingredientExtras];
 const free=all.filter((_,i)=>i<baseExtras.length&&extras[i][2]===0);
 const paid=all.filter((_,i)=>i>=baseExtras.length||extras[i][2]>0);
 return `<p class="option-hint">Extras wählen (kostenlose zuerst):</p><div class="extras extras-rows">${[...free,...paid].join('')}</div>`;
}
function priceOf(line){const p=products.find(x=>x.id===line.id);const defaults=defaultIds(p);const added=ingredients.reduce((sum,[id])=>sum+(!defaults.has(id)&&line.ingredients[id]===true?(ingredientAddPrices[id]||0):0),0);return line.price+added+extras.reduce((n,[id,,price])=>n+(line.extras[id]?price:0),0)}
function newLine(p){return {drink:p.category==='combos'?'water':null,uid:++serial,id:p.id,name:p.name,price:p.price,image:p.image,category:p.category,ingredients:Object.fromEntries(ingredients.map(([id])=>[id,defaultIds(p).has(id)])),extras:{},halved:false,note:''}}
function missingStock(id){return stockUnavailable.includes(id)}
function productUnavailable(p){if(!p)return true;if(missingStock(p.shawarmaId||p.id))return true;if(isShawarma(p)){if(['lavash','meat',...(p.defaultCheese?['cheese']:[]),...(p.mushroom?['mushroom']:[]),...(p.hawaii?['pineapple','corn']:[]),...((p.shawarmaId||p.id)==='spicy'?['hot']:[])].some(missingStock))return true;if(p.category==='combos'&&(missingStock('fries')||missingStock(p.shawarmaId)||drinkChoices.every(([id])=>missingStock(id))))return true;}return false}
function lineUnavailable(x){return productUnavailable(products.find(p=>p.id===x.id))||(x.category==='combos'&&missingStock(x.drink))|| (isShawarma(x)&&(Object.keys(x.ingredients).some(id=>x.ingredients[id]&&missingStock(id))||Object.keys(x.extras).some(id=>x.extras[id]&&missingStock(id))))}
function stockLabel(){return tr('Vorübergehend nicht verfügbar','Временно недоступно')}
function renderHomeCategories(){document.querySelectorAll('.home-category-panel').forEach(panel=>{const cat=panel.dataset.cat;panel.innerHTML=products.filter(p=>p.category===cat&&!p.id.startsWith('combo-')).map(p=>`<button class="home-product ${productUnavailable(p)?'stock-unavailable':''}" data-add="${p.id}" ${productUnavailable(p)?'disabled':''}><img src="assets/${p.image}" alt=""><span><strong>${esc(p.name)}</strong><small>${esc(p.desc)}</small></span><b>${productUnavailable(p)?stockLabel():euro(p.price)+' +'}</b></button>`).join('')})}
function productBadge(p){const labels={spicy:['🌶 Scharf','hot'],classic:['Bestseller','best'],hawaii:['Neu','new']};const b=labels[p.id];return b?`<span class="product-badge badge-${b[1]}">${b[0]}</span>`:''}
function renderMenu(){
 const items=products.filter(p=>!p.id.startsWith('combo-')&&(filter==='all'||p.category===filter));
 const html=items.map(p=>`<article class="product ${isShawarma(p)?'product-collapsible':''}" data-product="${p.id}" ${productUnavailable(p)?'data-stock-off="true"':''}>
 <button type="button" class="product-summary" data-toggle-ingredients="${p.id}" aria-expanded="false" aria-label="${esc(p.name)}: Zutaten ansehen">
 ${productBadge(p)}
 <span class="product-thumb ${isShawarma(p)?'shawarma-thumb':''}"><img src="assets/${p.image}" alt="" loading="lazy"></span>
 <span class="product-main"><span class="product-name">${esc(p.name)}</span><span class="product-description">${esc(p.desc)}</span><span class="price">${euro(p.price)}</span></span>
 ${isShawarma(p)?'<span class="product-toggle-label">Zutaten ansehen <span class="product-toggle-chevron" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg></span></span>':''}
 </button>
 ${isShawarma(p)?`<div class="product-ingredients" hidden>${ingredientsHtml(null,false,p)}${allergenHtml(p)}</div>`:allergenHtml(p)}
 <button type="button" class="product-order-btn" data-add="${p.id}" ${productUnavailable(p)?'disabled':''} aria-label="${esc(p.name)} bestellen">${productUnavailable(p)?stockLabel():isShawarma(p)?'🌯 Jetzt bestellen':'＋ Hinzufügen'} <span aria-hidden="true">›</span></button>
 </article>`).join('');
 $('#products').innerHTML=html;$('#homeProducts').innerHTML=html;
}
function toggleProductIngredients(button){
 const card=button.closest('.product');if(!card)return;
 const details=card.querySelector('.product-ingredients');if(!details)return;
 const opening=details.hidden;
 const list=card.parentElement;
 list.querySelectorAll('.product-ingredients:not([hidden])').forEach(el=>{
  el.hidden=true;const other=el.closest('.product');other.classList.remove('ingredients-open');
  const trigger=other.querySelector('.product-summary');trigger.setAttribute('aria-expanded','false');
  const label=trigger.querySelector('.product-toggle-label');if(label)label.innerHTML='Zutaten ansehen <span class="product-toggle-chevron" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg></span>';
 });
 details.hidden=!opening;card.classList.toggle('ingredients-open',opening);
 button.setAttribute('aria-expanded',String(opening));
 const label=button.querySelector('.product-toggle-label');if(label)label.innerHTML=(opening?'Zutaten schließen':'Zutaten ansehen')+' <span class="product-toggle-chevron" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg></span>';
}

function add(id,button){if(activeOrder()){go('order');return;}const p=products.find(x=>x.id===id);if(!p||productUnavailable(p))return;const line=newLine(p);if(isShawarma(line))for(const id of Object.keys(line.ingredients))if(missingStock(id))line.ingredients[id]=false;if(line.category==='combos')line.drink=drinkChoices.find(([id])=>!missingStock(id))?.[0];cart.push(line);saveCart();renderOrder();updateBottom();showAddedToast(p.name);vibrateOrder(35);if(button){button.classList.add('added-success');const original=button.innerHTML;button.innerHTML='<span class="button-check">✓</span> Hinzugefügt';button.disabled=true;setTimeout(()=>{if(button.isConnected){button.innerHTML=original;button.disabled=false;button.classList.remove('added-success')}},1050)}}
let toastTimer;function showAddedToast(name){const toast=$('#addedToast');if(!toast)return;toast.querySelector('.toast-product').textContent=name;toast.classList.add('show');toast.setAttribute('aria-hidden','false');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{toast.classList.remove('show');toast.setAttribute('aria-hidden','true')},2700)}
function remove(uid){cart=cart.filter(x=>x.uid!==uid);saveCart();renderOrder();updateBottom()}
function minus(id){const i=cart.map(x=>x.id).lastIndexOf(id);if(i>=0){cart.splice(i,1);saveCart();renderOrder();updateBottom()}}
function amount(){return cart.reduce((s,x)=>s+priceOf(x),0)}
function row(p){const count=cart.filter(x=>x.id===p.id).length;return `<div class="order-product"><div class="order-product-top"><div class="order-thumb ${isShawarma(p)?'shawarma-thumb':''}"><img src="assets/${p.image}" alt="" loading="lazy"></div><div class="name"><strong>${esc(p.name)}</strong><small>${euro(p.price)} · ${esc(p.desc)}</small></div><div class="qty"><button data-minus="${p.id}" aria-label="${esc(p.name)} reduzieren" ${count===0?'disabled':''}>−</button><span>${count}</span><button data-add="${p.id}" aria-label="${esc(p.name)} hinzufügen">+</button></div></div></div>`}
function renderOrder(){renderCart();syncActiveOrder()}
function renderCart(){const el=$('#cartItems');el.innerHTML=cart.length?cart.map(x=>`<article class="cart-line">${lineUnavailable(x)?`<p class="stock-cart-warning">${stockLabel()} — ${tr('Bitte entfernen oder ändern','Удалите или измените позицию')}</p>`:''}<div class="cart-line-top"><img class="cart-mini-photo" src="assets/${x.image}" alt=""><strong>${esc(x.name)}</strong><strong>${euro(priceOf(x))}</strong><div class="cart-qty"><button data-remove="${x.uid}" aria-label="Eine Portion entfernen">−</button><span>1</span><button data-add="${x.id}" aria-label="Eine Portion hinzufügen">+</button></div><button class="remove-line" data-remove="${x.uid}" aria-label="Entfernen">×</button></div>${x.category==='combos'?`<div class="combo-included">✓ Shawarma · ✓ Pommes Frites · ✓ 1 Getränk</div><label class="combo-drink">Getränk wählen<select data-combo-drink="${x.uid}">${drinkChoices.map(([id,label])=>`<option value="${id}" ${x.drink===id?'selected':''} ${missingStock(id)?'disabled':''}>${label}</option>`).join('')}</select></label>`:''}${comboOffer(x)}${isShawarma(x)?`<p class="option-hint"><strong>Shawarma zusammenstellen</strong> · Zutaten antippen, um sie abzuwählen:</p>${ingredientsHtml(x,true)}${extrasHtml(x)}<label class="half-option"><input type="checkbox" data-half="${x.uid}" ${x.halved?'checked':''}>In zwei Hälften schneiden (kostenlos)</label><label class="line-comment">Kommentar zu dieser Shawarma<textarea rows="2" maxlength="220" data-note="${x.uid}" placeholder="z. B. wenig Soße, extra knusprig ...">${esc(x.note)}</textarea></label>`:''}</article>`).join(''):'<p class="muted">Noch keine Produkte ausgewählt.</p>';$('#total').textContent=euro(amount());$('#checkoutTotal').textContent=euro(amount());renderAddons()}
function updateBottom(){const count=cart.length;$('#bottomCount').textContent=count+' Artikel · '+euro(amount());$('#bottomBar').classList.toggle('visible',count>0&&!$('#order').classList.contains('active'));const badge=$('#bottomCount');badge.classList.remove('count-pop');void badge.offsetWidth;badge.classList.add('count-pop');document.body.classList.toggle('has-cart',count>0);document.querySelectorAll('.bottom-checkout').forEach(b=>b.classList.toggle('cart-ready',count>0))}
const ORDER_QUEUE='schawa-kitchen-demo-v1', LAST_ORDER='schawa-last-web-order-v1';
const SERVER_ORDER_KEY='schawa-server-order-v15', RECEIPT_KEY='schawa-server-receipt-v16', PENDING_KEY='schawa-pending-order-v15';
let stockUnavailable=[], catalogReady=false;
function readLocal(k){try{return JSON.parse(localStorage.getItem(k)||'null')}catch{return null}}
function migrateReceipt(){const ref=readLocal(SERVER_ORDER_KEY);if(!ref||readLocal(RECEIPT_KEY))return;const old=readLocal(ORDER_QUEUE);const o=old?.orders?.find(x=>x.id===ref.id);if(o)localStorage.setItem(RECEIPT_KEY,JSON.stringify(o));}
migrateReceipt();
try{const pending=sessionStorage.getItem(PENDING_KEY);if(pending&&!localStorage.getItem(PENDING_KEY))localStorage.setItem(PENDING_KEY,pending)}catch(_){}
const ru=()=>document.documentElement.lang==='ru', tr=(de,r)=>ru()?r:de;
function activeOrder(){const o=lastOrder();return o&&!['done','cancelled','no_show'].includes(o.status)?o:null}
function lastOrder(){const ref=readLocal(SERVER_ORDER_KEY),o=readLocal(RECEIPT_KEY);return ref&&o&&ref.id===o.id?o:null}
function receiptStatus(o){return ({new:tr('Wartet auf Bestätigung','Ожидает подтверждения'),waiting:tr('Bestätigt','Подтверждён'),due:tr('Bestätigt','Подтверждён'),cooking:tr('In Zubereitung','Жарится'),ready:tr('Abholbereit','Готов к выдаче'),done:tr('Abgeholt','Выдан'),cancelled:o.cancelledBy==='customer'?tr('Storniert','Отменён'):tr('Abgelehnt','Отклонён'),no_show:tr('Nicht abgeholt','Не забрали')})[o.status]||o.status}
function receiptColor(id){return ['#f1f2f3','#171717']}
function receiptItemName(i){return i.id==='combo-classic'?'Shawarma Klassik Menü':i.id==='combo-xl'?'Shawarma XL Menü':i.name;}
function receiptCombo(i){if(!['combo-classic','combo-xl'].includes(i.id)&&!String(i.id).startsWith('menu-'))return '';const n=String(i.id).startsWith('menu-')?i.name.replace(/ Menü$/,''):i.id==='combo-classic'?'Shawarma Klassik':'Shawarma XL',d=({water:tr('Mineralwasser','Вода'),cola:'Coca-Cola',sprite:'Sprite'})[i.drink]||tr('Getränk nicht angegeben','Напиток не указан');return `<small style="display:block;line-height:1.6;margin:4px 0 4px 12px">${i.qty} × ${esc(n)}<br>${i.qty} × ${tr('Pommes frites','Картофель фри')}<br>${i.qty} × ${esc(d)}</small>`;}
function itemDetails(i){return [...(i.remove||[]).map(v=>tr('Ohne ','Без: ')+v),...(i.extras||[]).map(v=>'+ '+v),i.note].filter(Boolean).join(' · ')}
let receiptPrevious='';
function receiptProgress(o){const stage=({new:1,waiting:2,due:2,cooking:3,ready:4,done:4})[o.status]||0;const labels=[tr('Bestellt','Заказ'),tr('Bestätigt','Подтверждён'),tr('Zubereitung','Жарится'),tr('Abholbereit','К выдаче')];const icon=stage===3?`<svg viewBox="0 0 80 80" aria-hidden="true"><g class="grill-heat" fill="none" stroke="#d97706" stroke-width="3" stroke-linecap="round"><path d="M24 28q-7-6 0-12t0-10"/><path d="M40 28q-7-6 0-12t0-10"/><path d="M56 28q-7-6 0-12t0-10"/></g><g class="grill-meat"><path d="M18 37q8-12 22-5t22 8q5 12-12 15L24 53q-13-3-6-16" fill="#b86b39" stroke="#80401f" stroke-width="2"/><path d="m27 35-5 14m17-15-5 17m17-13-5 15" stroke="#713f24" stroke-width="3" stroke-linecap="round"/></g><path d="M12 58h56l-8 9H20z" fill="#16754b"/><path d="m26 67-3 8m31-8 3 8" stroke="#16754b" stroke-width="4" stroke-linecap="round"/></svg>`:stage===4?`<svg viewBox="0 0 80 80" aria-hidden="true"><g class="ready-bag"><path d="M19 27h42l5 44H14z" fill="#d9ad70" stroke="#946633" stroke-width="2" stroke-linejoin="round"/><path d="M29 29V20a11 11 0 0 1 22 0v9" fill="none" stroke="#946633" stroke-width="4" stroke-linecap="round"/><circle cx="40" cy="48" r="12" fill="#16754b"/><path d="m34 48 4 4 8-9" fill="none" stroke="white" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></g><g class="bag-spark" stroke="#16754b" stroke-width="2.5" stroke-linecap="round"><path d="M8 17v8m-4-4h8m60-8v8m-4-4h8"/></g></svg>`:stage===2?'✓':stage===1?'…':'!';return `<div class="receipt-status ${stage?'':'receipt-failed'}"><span class="receipt-symbol ${stage===3||stage===4?'receipt-illustration':''}">${icon}</span><h2>${esc(receiptStatus(o))}</h2></div><div class="receipt-progress" aria-label="${esc(receiptStatus(o))}"><div class="receipt-track"><div id="receiptFill" style="width:${Math.max(0,stage-1)*100/3}%"></div></div>${labels.map((label,i)=>`<div class="receipt-step ${i<stage?'reached':''} ${i===stage-1?'current':''}"><span>${i+1<stage?'✓':i+1}</span><small>${label}</small></div>`).join('')}</div>`}
function showReceipt(open=true){const o=activeOrder();if(!o)return;const [bg,fg]=receiptColor(o.id);const key=JSON.stringify([o.id,o.status,o.pickup,o.mode,o.items,o.note,ru()]);if(receiptPrevious===key&&!open)return;const oldWidth=$('#receiptFill')?.style.width;receiptPrevious=key;$('#receiptBody').innerHTML=`${receiptProgress(o)}<div class="receipt-num" style="background:${bg};color:${fg}">#${esc(o.id.slice(-6))}</div><div class="receipt-time">${tr('Abholung ca.','Выдача около')} ${esc(o.pickup)}</div><div id="orderCountdown" class="order-countdown"></div><button type="button" id="enableReadyNotice" class="ready-optin" hidden>${tr('Benachrichtigung aktivieren','Включить уведомление')}</button><small>${esc(o.mode==='На месте'?tr('Vor Ort essen','На месте'):tr('Zum Mitnehmen','С собой'))}</small>${o.items.map(i=>`<div class="receipt-item"><strong>${i.qty} × ${esc(receiptItemName(i))}</strong>${receiptCombo(i)}<small>${esc(itemDetails(i))}</small></div>`).join('')}${o.note?`<small>${esc(o.note)}</small>`:''}${receiptActions(o)}<div class="receipt-total">${tr('Zahlung vor Ort','Оплата на месте')}: ${euro(o.items.reduce((a,i)=>a+i.price*i.qty,0))}</div><small>${tr('Demo · Bitte Bestellnummer bei Abholung zeigen.','Демо · Покажите номер при получении.')}</small>`;const fill=$('#receiptFill');if(fill&&oldWidth){const target=fill.style.width;fill.style.width=oldWidth;requestAnimationFrame(()=>requestAnimationFrame(()=>fill.style.width=target))}if(open)go('order')}

let checkoutBusy=false;
var sgState=null,sgOffset=0,sgSeen="";
function sgNow(){return Date.now()+sgOffset;}
function berlinPickup(minutes){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(new Date(sgNow()+minutes*60000));}
function apiLine(x){const p=products.find(p=>p.id===x.id),base=defaultIds(p),line={sku:x.id,qty:1};if(isShawarma(x)){
 line.ingredients=Object.fromEntries(ingredients.filter(([id])=>x.ingredients[id]!==base.has(id)).map(([id])=>[id,!!x.ingredients[id]]));
 line.extras=Object.fromEntries(extras.filter(([id])=>x.extras[id]).map(([id])=>[id,true]));
 line.halved=!!x.halved;
 }if(x.category==='combos')line.drink=x.drink;
 if(x.note)line.note=x.note;
 return line;
}
function pendingNotice(){let d=document.getElementById('sgPending');if(!d){d=document.createElement('dialog');d.id='sgPending';d.style.cssText='border:0;border-radius:20px;padding:24px;width:min(88vw,400px);text-align:center';document.body.append(d);}d.replaceChildren();const h=document.createElement('h2');h.textContent=tr('Verbindung unterbrochen','Связь прервалась');const p=document.createElement('p');p.textContent=tr('Wir prüfen deine Bestellung. Bitte nicht erneut bestellen.','Проверяем ваш заказ. Не оформляйте его повторно.');const b=document.createElement('button');b.type='button';b.textContent=tr('Bestellung prüfen','Проверить заказ');b.onclick=()=>{d.close();recoverPending(true)};b.style.cssText='background:#c90020;color:white;border:0;border-radius:12px;padding:14px;width:100%;font-weight:bold';d.insertAdjacentHTML('beforeend',sgIcon('offline'));d.append(h,p,b);if(!d.open)d.showModal();}
async function transmitPending(p,recoverOnly,retry){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),12000);let r,data;try{r=await fetch('/api/orders/create.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...p.body,...(recoverOnly?{recover_only:true}:{})}),cache:'no-store',signal:controller.signal});data=await r.json();}finally{clearTimeout(timer)}
 if(recoverOnly&&r.status===404)return false;
 if(!r.ok){if(!recoverOnly&&!retry&&[400,405,413,415,422,429].includes(r.status)){localStorage.removeItem(PENDING_KEY);sessionStorage.removeItem(PENDING_KEY);}throw Error(data.error||String(r.status));}
 if(!/^\d{6}$/.test(data.number)||! /^[a-f0-9]{64}$/i.test(data.token)||!data.pickup_at)throw Error('invalid_response');
 const due=sgAbsolute(data.pickup_at);const o={id:'W-'+data.number,date:new Date().toISOString(),due,pickup:new Date(due).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Berlin'}),status:'new',source:'Сайт',mode:p.body.fulfillment==='eat_in'?'На месте':'С собой',items:p.items,note:p.body.comment};
 localStorage.setItem(RECEIPT_KEY,JSON.stringify(o));localStorage.setItem(SERVER_ORDER_KEY,JSON.stringify({number:data.number,token:data.token,id:o.id}));sgRemember({number:data.number,token:data.token,id:o.id});localStorage.removeItem(PENDING_KEY);sessionStorage.removeItem(PENDING_KEY);cart=[];saveCart();renderOrder();updateBottom();$('#comment').value='';document.getElementById('sgPending')?.close();showReceipt();refreshServerOrder();return true;}
async function recoverPending(manual=false){if(checkoutBusy)return;const raw=localStorage.getItem(PENDING_KEY);if(!raw)return;checkoutBusy=true;try{const p=JSON.parse(raw);if(!p.body||!Array.isArray(p.items)){if(manual)alert(tr('Bitte Personal fragen.','Уточните у кассира.'));return;}if(await transmitPending(p,true,true))return;if(manual){if(confirm(tr('Noch keine Bestätigung gefunden. Dieselbe Bestellung erneut senden?','Подтверждение не найдено. Повторить отправку того же заказа?')))await transmitPending(p,false,true);}}catch(e){if(manual)pendingNotice();}finally{checkoutBusy=false;}}
window.addEventListener('online',()=>recoverPending());window.addEventListener('load',()=>recoverPending());setInterval(()=>recoverPending(),15000);
async function sendOrder(e){e.preventDefault();if(checkoutBusy)return;if(activeOrder()){showReceipt();return;}if(localStorage.getItem(PENDING_KEY)){await recoverPending(true);return;}if(!cart.length)return;
 if(!navigator.onLine){sgNotice(true);return;}if(!catalogReady){alert(tr('Serverkatalog nicht verfügbar. Bitte erneut versuchen.','Каталог сервера недоступен. Повторите попытку.'));return;}
 if(cart.some(lineUnavailable)){alert(tr('Ein Produkt ist nicht verfügbar.','Один из товаров закончился.'));return;}

 checkoutBusy=true;const button=$('#orderForm button[type="submit"]');if(button)button.disabled=true;
 try{
 if(!await sgRefresh(false)||!sgState.slots.includes(Number($('#pickup').value))){sgNotice(true);return;}
 const lines=cart.map(apiLine);
 const quoteRes=await fetch('/api/orders/quote.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:lines}),cache:'no-store'});
 const quote=await quoteRes.json();if(!quoteRes.ok)throw Error('quote: '+(quote.error||quoteRes.status));
 const expected=Math.round(amount()*100);if(quote.total_cents!==expected){alert(tr('Der Serverpreis weicht vom Warenkorb ab. Bitte Bestellung prüfen.','Цена на сервере отличается от корзины. Проверьте заказ.')+' '+euro(quote.total_cents/100));return;}
 const minutes=Number($('#pickup').value);
 const mode=document.querySelector('input[name="orderMode"]:checked')?.value==='Vor Ort essen'?'eat_in':'takeaway';
 const body={request_key:crypto.randomUUID(),fulfillment:mode,pickup_at:sgState.times?.[minutes]||berlinPickup(minutes),comment:$('#comment').value.trim(),items:lines};
 const items=cart.map(x=>({id:x.id,name:x.name,drink:x.drink,qty:1,price:priceOf(x),remove:isShawarma(x)?ingredients.filter(([id])=>defaultIds(products.find(p=>p.id===x.id)).has(id)&&x.ingredients[id]===false).map(v=>v[2]):[],extras:isShawarma(x)?extras.filter(([id])=>x.extras[id]).map(v=>v[1]):[],note:x.note||''}));
 localStorage.setItem(PENDING_KEY,JSON.stringify({body,items}));
 await transmitPending({body,items},false,false);
 }catch(err){console.error('Schawa V1.5 checkout',err);if(['ordering_paused','pickup_outside_hours','invalid_pickup'].includes(err.message)){await sgRefresh(false);sgNotice(true);return;}if(localStorage.getItem(PENDING_KEY))pendingNotice();else {sgState=null;sgNotice(true);}}
 finally{checkoutBusy=false;if(button)button.disabled=false;}
}
async function refreshServerOrder(){try{const raw=localStorage.getItem(SERVER_ORDER_KEY);if(!raw)return;const ref=JSON.parse(raw);if(!/^\d{6}$/.test(ref.number)||! /^[a-f0-9]{64}$/i.test(ref.token))return;
 const r=await fetch('/api/orders/?action=status&number='+encodeURIComponent(ref.number)+'&token='+encodeURIComponent(ref.token),{cache:'no-store'});if(!r.ok)return;const s=await r.json();const o=lastOrder();if(!o||o.id!==ref.id)return;
 let receiptChanged=false;if(Array.isArray(s.items)&&s.items.length===o.items.length){s.items.forEach((v,j)=>{const i=o.items[j];if((v.sku===i.id||"menu-"+v.sku===i.id)&&v.drink&&i.drink!==v.drink){i.drink=v.drink;receiptChanged=true;}});}if(receiptChanged){localStorage.setItem(RECEIPT_KEY,JSON.stringify(o));if(activeOrder())showReceipt(false);}
 const status=s.status==='delivered'?'done':s.status;if(o.status!==status){o.status=status;localStorage.setItem(RECEIPT_KEY,JSON.stringify(o));syncActiveOrder();updateBottom();if(status==='ready')checkReadyNotice(o);if(activeOrder())showReceipt(false);}
 }catch(err){console.warn('Status refresh',err)}}
setInterval(refreshServerOrder,5000);window.addEventListener('load',refreshServerOrder);
const orderButtons=new Map();
function syncActiveOrder(){
 const o=activeOrder(), active=!!o;
 const finished=lastOrder();
 const returnHome=!active&&finished&&['done','cancelled','no_show'].includes(finished.status)&&($('#order').classList.contains('active')||location.hash==='#order');
 if(!active&&finished?.status==='done')offerRating(finished);
 if(!active&&finished){sgArchive(finished);localStorage.removeItem(SERVER_ORDER_KEY);localStorage.removeItem(RECEIPT_KEY);localStorage.removeItem(LAST_ORDER);}
 if(active){cart=[];saveCart();if($('#cartItems').querySelector('.cart-line'))renderCart()}
 document.body.classList.toggle('has-active-order',active);
 $('#receipt').hidden=!active;document.querySelectorAll('dialog[open]').forEach(d=>{if(d.id==='receipt')d.close()});$('#orderForm').hidden=active;$('#order .cart-panel').hidden=active;$('#order .order-head').hidden=active;
 document.querySelectorAll('[data-page="order"]').forEach(b=>{
  if(!orderButtons.has(b))orderButtons.set(b,b.innerHTML);
  if(active){if(!b.dataset.activeLabel|| (b.closest('#drawer')&&!b.querySelector('.nav-symbol'))){b.dataset.activeLabel='1';b.innerHTML=b.closest('#drawer')?'<span class="nav-symbol"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M9 12l2 2 4-4"/></svg></span><span>Bestellung ansehen</span>':'<span>Bestellung ansehen</span><b aria-hidden="true">›</b>'}}
  else if(b.dataset.activeLabel){delete b.dataset.activeLabel;b.innerHTML=orderButtons.get(b)}
 });
 const fixed=$('#floatingPreorder');
 if(active){
  const key=[o.id,o.status,ru()].join('|');
  if(fixed.dataset.statusKey!==key){
   fixed.dataset.statusKey=key;fixed.dataset.stage=o.status;
   const paths={new:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',waiting:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',cooking:'<path class="fixed-steam" d="M8 8c-3-3 3-3 0-6m4 6c-3-3 3-3 0-6m4 6c-3-3 3-3 0-6"/><path d="M4 12h16v4a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5zm-2 2h2m16 0h2M3 10h18"/>',ready:'<path d="M5 7h14l2 14H3L5 7Zm4 0V5a3 3 0 0 1 6 0v2m-6 7 2 2 4-4"/>'};
   const icon=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${paths[o.status==='due'?'waiting':o.status]||paths.new}</svg>`;
   fixed.innerHTML=`<span class="fixed-order-icon" aria-hidden="true">${icon}</span><span class="fixed-order-copy"><strong>${tr('Bestellung ansehen','Посмотреть заказ')}</strong><small role="status"><span class="fixed-order-number">#${esc(String(o.id).slice(-6))}</span><span>${esc(receiptStatus(o))}</span></small></span><b aria-hidden="true">›</b>`;
  }
 }else{delete fixed.dataset.statusKey;delete fixed.dataset.stage;}
 if(active){showReceipt(false);updateOrderCountdown();checkReadyNotice(o)}else{receiptPrevious='';$('#receiptBody').innerHTML=''}
 if(returnHome)go('home');
}
