async function refreshStock(){try{const r=await fetch('/api/orders/?action=catalog',{cache:'no-store'});if(!r.ok)throw Error('catalog HTTP '+r.status);const d=await r.json();if(!Array.isArray(d.products)||!d.products.length)throw Error('empty catalog');const rows=new Map(d.products.map(p=>[p.sku,p]));const next=d.products.filter(p=>Number(p.available)!==1).map(p=>p.sku);let changed=!catalogReady||JSON.stringify(next)!==JSON.stringify(stockUnavailable);for(const p of products){if(p.id.startsWith('combo-'))continue;const row=rows.get(p.shawarmaId||p.id);if(!row){next.push(p.shawarmaId||p.id);continue;}const cents=Number(row.price_cents);if(!Number.isSafeInteger(cents)||cents<0)throw Error('invalid price');const price=cents/100+(p.id.startsWith('menu-')?4:0);if(p.price!==price){p.price=price;changed=true;}}stockUnavailable=[...new Set(next)];catalogReady=true;for(const x of cart){const p=products.find(p=>p.id===x.id);if(p&&x.price!==p.price){x.price=p.price;changed=true;}}if(changed){saveCart();renderMenu();renderHomeCategories();renderCart();updateBottom();}}catch(e){catalogReady=false;console.warn('Catalog refresh',e)}}
window.addEventListener('load',refreshStock);setInterval(refreshStock,30000);
