function refreshKitchenWarning(){const target=document.querySelector('.whatsapp-submit');if(!target)return;let el=$('#kitchenLoadWarning');if(!el){el=document.createElement('div');el.id='kitchenLoadWarning';el.setAttribute('role','status');target.before(el)}el.style.display=sgState?.in_hours?'':'none';if(!sgState?.in_hours)return;if(!sgState.accepting){el.dataset.key='paused';el.dataset.level='high';el.textContent=tr('Bestellpause','Приём заказов остановлен');return;}const l=SchawaLoad.read().level;const key=l+'|'+ru();if(el.dataset.key===key)return;el.dataset.key=key;el.dataset.level=l;const texts={normal:[tr('Normale Auslastung','Обычная загруженность'),tr('Keine langen Wartezeiten zu erwarten','Приготовим без долгого ожидания')],busy:[tr('Viele Bestellungen','Повышенная загруженность'),tr('Die Zubereitung kann etwas länger dauern','Приготовление может занять немного больше времени')],high:[tr('Hohe Auslastung','Высокая загруженность'),tr('Viele Bestellungen. Verzögerungen möglich.','Сейчас много заказов. Возможна задержка.')]};const t=texts[l]||texts.normal;el.innerHTML=`<strong>${t[0]}</strong><small>${t[1]}</small>`;}

refreshKitchenWarning();setInterval(refreshKitchenWarning,1000);window.addEventListener('storage',refreshKitchenWarning);

function vibrateOrder(pattern){try{navigator.vibrate?.(pattern)}catch(_){}}
function renderAddons(){const el=$('#cartAddons');if(!el)return;const scroll=el.querySelector('.addon-grid')?.scrollLeft||0;const list=products.filter(p=>['sides','drinks'].includes(p.category)&&!productUnavailable(p));el.hidden=!cart.length||!list.length||!!activeOrder();el.innerHTML=el.hidden?'':`<h3>${tr('Noch etwas dazu?','Добавить к заказу?')}</h3><div class="addon-grid">${list.map(p=>`<button type="button" class="addon-card" data-add="${p.id}" aria-label="${esc(p.name)} +"><img src="assets/${p.image}" alt="" loading="lazy"><strong>${esc(p.name)}</strong><span>${euro(p.price)} <b>+</b></span></button>`).join('')}</div>`;const grid=el.querySelector('.addon-grid');if(grid)grid.scrollLeft=scroll;}
function updateOrderCountdown(){const o=activeOrder(),el=$('#orderCountdown');if(!o||!el)return;const due=Number(o.due),left=Math.max(0,Math.ceil((due-Date.now())/1000));const value=o.status==='ready'?tr('Jetzt abholbereit!','Можно забирать!'):!Number.isFinite(due)||due<=0?tr('Abholzeit wird bestätigt','Время выдачи уточняется'):left===0?tr('Abholzeit erreicht · Bitte Status beachten','Время выдачи наступило · Следите за статусом'):tr('Voraussichtlich noch ','Ориентировочно осталось ')+Math.floor(left/60)+':'+String(left%60).padStart(2,'0');if(el.textContent!==value)el.textContent=value;const b=$('#enableReadyNotice');if(b)b.hidden=o.status==='ready'||!('Notification' in window)||Notification.permission!=='default';}
function checkReadyNotice(o){if(!o||o.status!=='ready')return;const key='schawa-ready-notified-'+o.id;try{if(localStorage.getItem(key))return;localStorage.setItem(key,'1')}catch(_){return}vibrateOrder([180,100,180,100,300]);const el=$('#readyNotice');el.hidden=false;el.querySelector('strong').textContent=tr('Deine Bestellung ist fertig!','Ваш заказ готов!');el.querySelector('p').textContent='#'+o.id.slice(-6)+' · '+tr('Jetzt abholen','Можно забирать');if('Notification' in window&&Notification.permission==='granted'){try{const n=new Notification(tr('Deine Bestellung ist fertig!','Ваш заказ готов!'),{body:'#'+o.id.slice(-6),tag:o.id});n.onclick=()=>{window.focus();go('order');n.close()}}catch(_){}}}
document.addEventListener('click',async e=>{if(e.target.closest('#enableReadyNotice')){try{await Notification.requestPermission()}catch(_){}updateOrderCountdown()}if(e.target.closest('#readyNoticeClose')||e.target.closest('#readyNoticeOpen'))$('#readyNotice').hidden=true;});
setInterval(()=>{updateOrderCountdown();const o=activeOrder();if(!o)$('#readyNotice').hidden=true;},1000);

function allergenHtml(p){const known=isShawarma(p)?['Gluten (Lavash)',...(p.defaultCheese?['Milch (Käse)']:[])]:p.id==='shrimp'?['Krebstiere']:[];const r=isShawarma(p)?['Глютен (лаваш)',...(p.defaultCheese?['Молоко (сыр)']:[])]:p.id==='shrimp'?['Ракообразные']:[];return `<details class="allergen-info"><summary>Allergene / Аллергены</summary><small>${(ru()?r:known).join(', ')}${known.length?' · ':''}${tr('Vorläufige Angaben. Weitere Allergene und Kreuzkontakte noch nicht geprüft. Bitte Personal fragen.','Предварительные сведения. Другие аллергены и перекрёстный контакт не проверены. Уточните у персонала.')}</small></details>`}
function comboOffer(x){if(x.category==='combos')return `<button type="button" class="combo-upgrade" data-downgrade="${x.uid}">${tr('Menü entfernen','Убрать комплект')}</button>`;const p=products.find(p=>p.id==='menu-'+x.id);if(!p||productUnavailable(p)||lineUnavailable(x))return '';const extra=p.price-x.price;return `<button type="button" class="combo-upgrade" data-upgrade="${x.uid}"><strong>${tr('Zum Menü upgraden','Дополнить до комбо')} · +${euro(extra)}</strong><small>${tr('Pommes + Getränk nach Wahl','Картошка фри + напиток на выбор')}</small></button>`}
function receiptActions(o){return `<div class="receipt-actions"><button type="button" data-share-order>${tr('Bestellung teilen','Поделиться заказом')}</button>${['new','waiting','due'].includes(o.status)&&!(o.cookStarted||[]).length?`<button type="button" data-cancel-order>${tr('Bestellung stornieren','Отменить заказ')}</button>`:''}</div>`}
function offerRating(o){if(document.getElementById('ratingDialog')||o.rating||localStorage.getItem('schawa-rating-skip-'+o.id))return;const d=document.createElement('dialog');d.id='ratingDialog';d.className='rating-dialog';d.innerHTML=`<h2>${tr('Wie war deine Bestellung?','Как вам заказ?')}</h2><p>#${esc(o.id.slice(-6))}</p><div class="rating-stars">${[1,2,3,4,5].map(n=>`<button type="button" data-rating="${n}" aria-label="${n}/5">★</button>`).join('')}</div><button type="button" data-rating-skip>${tr('Später','Пропустить')}</button>`;document.body.append(d);const close=()=>{localStorage.setItem('schawa-rating-skip-'+o.id,'1');d.close();d.remove()};d.addEventListener('cancel',e=>{e.preventDefault();close()});d.onclick=e=>{const b=e.target.closest('[data-rating]');if(b){localStorage.setItem('schawa-local-rating-'+o.id,b.dataset.rating);close()}else if(e.target.closest('[data-rating-skip]'))close()};d.showModal()}
document.addEventListener('click',async e=>{const down=e.target.closest('[data-downgrade]');if(down){const x=cart.find(x=>x.uid===+down.dataset.downgrade),p=x&&products.find(p=>p.id===products.find(v=>v.id===x.id)?.shawarmaId);if(p){Object.assign(x,{id:p.id,name:p.name,price:p.price,image:p.image,category:p.category,drink:null});saveCart();renderCart();updateBottom();}}const up=e.target.closest('[data-upgrade]');if(up){const x=cart.find(x=>x.uid===+up.dataset.upgrade),p=x&&products.find(p=>p.id==='menu-'+x.id);if(!p||productUnavailable(p)||lineUnavailable(x))return;Object.assign(x,{id:p.id,name:p.name,price:p.price,image:p.image,category:p.category,drink:drinkChoices.find(([id])=>!missingStock(id))?.[0]});saveCart();renderCart();updateBottom();vibrateOrder(35)}if(e.target.closest('[data-cancel-order]')){alert(tr('Bitte beim Personal stornieren.','Для отмены обратитесь к кассиру.'));}if(e.target.closest('[data-share-order]')){const o=activeOrder();if(!o)return;const text=tr('Schawa Grill · Bestellung','Schawa Grill · Заказ')+' #'+o.id.slice(-6)+' · '+o.pickup+' · '+receiptStatus(o);try{if(navigator.share)await navigator.share({text});else if(navigator.clipboard) {await navigator.clipboard.writeText(text);alert(tr('Kopiert','Скопировано'))}else prompt(tr('Bestellung kopieren','Скопируйте заказ'),text)}catch(err){if(err.name!=='AbortError')prompt(tr('Bestellung kopieren','Скопируйте заказ'),text)}}});

function sgNotice(force=false){const d=sgState;const state=!navigator.onLine?'offline':d?.state||'unavailable';if(!force&&(state==='open'||sgSeen===state))return;sgSeen=state;let box=document.getElementById('sgHoursDialog');if(!box){box=document.createElement('dialog');box.id='sgHoursDialog';box.style.cssText='border:0;border-radius:20px;padding:24px;width:min(88vw,400px);text-align:center;color:#202020;box-shadow:0 12px 60px #0004';document.body.append(box);const style=document.createElement('style');style.textContent='#sgHoursDialog::backdrop{background:#0008}';document.head.append(style);}const texts={offline:[tr('Hoppla! Kein Internet.','Упс! Нет интернета.'),tr('Dein Internet macht wohl gerade eine Shawarma-Pause. 🌯 Keine Sorge, dein Warenkorb bleibt gespeichert.','Интернет взял паузу. Корзина сохранена.')],paused:[tr('Hoppla! Kurze Bestellpause.','Упс! Небольшая пауза.'),tr('Bei uns ist gerade etwas schiefgelaufen. Aber keine Sorge – wir schrauben schon daran!','Что-то пошло не так, но мы уже чиним!')],before_open:[tr('Wir öffnen bald!','Скоро открываемся!'),tr('Heute öffnen wir um ','Сегодня открываемся в ')+(d?.opens||'')+tr(' Uhr. Vorbestellung möglich.','. Можно сделать предзаказ.')],closed:[tr('Für heute geschlossen','Сегодня уже закрыто'),tr('Morgen sind wir wieder für dich da.','Завтра снова работаем.')],last_orders:[tr('Heute keine weiteren Bestellungen','Сегодня больше не принимаем заказы'),tr('Morgen sind wir wieder für dich da.','Ждём вас завтра.')],open:[tr('Abholzeit aktualisiert','Время выдачи обновлено'),tr('Bitte wähle eine verfügbare Abholzeit.','Выберите доступное время выдачи.')],unavailable:[tr('Bestellungen derzeit nicht verfügbar','Заказы временно недоступны'),tr('Bitte versuche es später erneut.','Попробуйте позже.')]};const t=texts[state]||texts.unavailable;box.replaceChildren();const h=document.createElement('h2');h.textContent=t[0];const p=document.createElement('p');p.textContent=t[1];const btn=document.createElement('button');btn.type='button';btn.textContent=state==='paused'?tr('Alles klar!','Всё понятно!'):tr('Verstanden','Понятно');btn.style.cssText='background:#c90020;color:white;border:0;border-radius:12px;padding:14px;width:100%;font-weight:bold';if(state==='offline'||state==='unavailable')btn.textContent=tr('Erneut versuchen','Повторить попытку');btn.onclick=()=>{box.close();if(state==='offline'||state==='unavailable')sgRefresh(true);};box.insertAdjacentHTML('beforeend',sgIcon(state));box.append(h,p);if(state==='paused'){const q=document.createElement('p');q.textContent=tr('Bald rollen die Shawarmas wieder. 🌯','Скоро снова крутим шаурму! 🌯');q.style.fontWeight='bold';const small=document.createElement('p');small.textContent=tr('Dein Warenkorb bleibt gespeichert.','Корзина сохранена.');box.append(q,small);}box.append(btn);if(!box.open)box.showModal();}
async function sgRefresh(notice=true){try{const res=await fetch('/api/order-control.php',{cache:'no-store'});if(!res.ok)throw Error('hours');const d=await res.json();if(!Array.isArray(d.slots)||!Number.isFinite(Date.parse(d.server_time)))throw Error('hours');sgState=d;sgOffset=Date.parse(d.server_time)-Date.now();}catch{sgState=null;}const slots=sgState?.slots||[];const select=$('#pickup');const previous=select.value;const pre=sgState?.state==='before_open';const values=pre?slots:Array.from({length:10},(_,i)=>15+i*5);select.replaceChildren(...values.map(n=>new Option(String(n),String(n))));select.value=previous;$('#pickupOptions').innerHTML=values.map(n=>`<button type="button" class="pickup-option" data-minutes="${n}">${pre?esc(sgState.times[n].slice(11,16)):n+' Min'}</button>`).join('');$('#pickupOptions').style.display=slots.length?'':'none';document.querySelector('.pickup-label').textContent=pre?tr('Abholung zur Öffnung','Выдача после открытия'):tr('Abholung in *','Выдача через');for(const o of select.options)o.disabled=!slots.includes(Number(o.value));if(!slots.includes(Number(select.value)))select.value=slots.length?String(slots[0]):'';document.querySelectorAll('#pickupOptions [data-minutes]').forEach(b=>{b.disabled=!slots.includes(Number(b.dataset.minutes));b.classList.toggle('selected',Number(b.dataset.minutes)===Number(select.value));b.setAttribute('aria-pressed',String(Number(b.dataset.minutes)===Number(select.value)));});const status=document.querySelector('.status-text');if(status)status.textContent=!sgState?tr('Status unbekannt','Статус неизвестен'):sgState?.state==='open'?tr('Geöffnet','Открыто'):tr('Geschlossen','Закрыто');updatePickupEstimate();if(!slots.length&&$('#pickupEstimate'))$('#pickupEstimate').textContent=tr('Keine Abholzeit verfügbar','Нет доступного времени выдачи');if(!slots.length&&sgState?.state==='before_open')$('#pickupEstimate').textContent=tr('Wir öffnen um ','Открываемся в ')+sgState.opens;refreshKitchenWarning();if(sgState&&['offline','unavailable'].includes(sgSeen)){document.getElementById('sgHoursDialog')?.close();sgSeen='';}if(notice&&!document.getElementById('sgPending')?.open)sgNotice();return !!sgState;}
function sgAbsolute(value){const parts=value.match(/\d+/g).map(Number);let t=Date.UTC(parts[0],parts[1]-1,parts[2],parts[3],parts[4],parts[5]);for(let i=0;i<2;i++){const a=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(new Date(t)).match(/\d+/g).map(Number);t+=Date.UTC(parts[0],parts[1]-1,parts[2],parts[3],parts[4],parts[5])-Date.UTC(a[0],a[1]-1,a[2],a[3],a[4],a[5]);}return t;}
function sgIcon(state){const art=state==='offline'?'<circle cx="60" cy="60" r="43" fill="#fff1d8"/><g fill="none" stroke="#b77b29" stroke-width="5" stroke-linecap="round"><path d="M28 48q32-28 64 0M39 61q21-18 42 0M50 74q10-8 20 0M27 25l66 70"/></g><circle cx="60" cy="86" r="4" fill="#b77b29"/>':state==='paused'?`<g transform="rotate(-12 60 60)"><path d="M34 30 Q60 5 86 30 L76 100 Q60 115 44 100Z" fill="#e8b878" stroke="#a96c35" stroke-width="2"/><ellipse cx="60" cy="30" rx="26" ry="13" fill="#a96c35"/><path d="M40 30l12 -8 12 8 12 -7" stroke="#659a45" stroke-width="8" fill="none"/><circle cx="51" cy="57" r="3"/><circle cx="70" cy="57" r="3"/><path d="M53 68q8 8 16 0" stroke="#513524" stroke-width="3" fill="none"/><path d="M85 58l13 9" stroke="#a96c35" stroke-width="5"/><g class="sg-wrench"><path d="M100 66V38l-8 -8 4 -10 5 10 6 -10 4 10 -7 8v28z" fill="#77858a"/></g></g>`:state==='closed'?'<path d="M75 18A43 43 0 1 0 102 88 43 43 0 0 1 75 18" fill="#d6a13e"/>':'<circle cx="60" cy="60" r="43" fill="#fff1d8" stroke="#b77b29" stroke-width="4"/><path d="M60 30v32l22 12" fill="none" stroke="#b77b29" stroke-width="5" stroke-linecap="round"/>';return `<svg aria-hidden="true" viewBox="0 0 120 120" width="110" height="110">${art}</svg>`;}
const sgStyle=document.createElement('style');sgStyle.textContent='@keyframes sgWrench{50%{transform:rotate(12deg)}}.sg-wrench{transform-origin:100px 66px;animation:sgWrench 1s ease-in-out infinite}@media(prefers-reduced-motion:reduce){.sg-wrench{animation:none}}#pickupOptions button:disabled{opacity:.35;cursor:not-allowed}';document.head.append(sgStyle);
sgRefresh();setInterval(()=>sgRefresh(),15000);window.addEventListener('focus',()=>sgRefresh());

document.addEventListener('click',e=>{if(e.target.closest('[data-sg-history]')){e.preventDefault();sgHistory();}});window.addEventListener('offline',()=>{sgState=null;sgRefresh(false);if(localStorage.getItem(PENDING_KEY))pendingNotice();else sgNotice(true);});window.addEventListener('online',()=>sgRefresh(true));

function sgArchive(o){try{const ref=readLocal(SERVER_ORDER_KEY);if(ref)sgRemember(ref);const list=JSON.parse(localStorage.getItem('sg-history-v1')||'[]');localStorage.setItem('sg-history-v1',JSON.stringify([o,...list.filter(x=>x.id!==o.id)].slice(0,50)));}catch{}}
function sgRemember(ref){try{if(!/^\d{6}$/.test(ref.number)||! /^[a-f0-9]{64}$/i.test(ref.token))return;const list=readLocal('sg-history-refs-v1')||[];localStorage.setItem('sg-history-refs-v1',JSON.stringify([ref,...list.filter(x=>x.token!==ref.token)].slice(0,50)));}catch{}}
let sgHistoryGeneration=0;
async function sgHistory(){const host=document.getElementById('sgHistoryList');if(!host)return;const subtitle=document.getElementById("sgHistorySubtitle");if(subtitle)subtitle.textContent=tr("Deine bisherigen Bestellungen","Твои предыдущие заказы");const generation=++sgHistoryGeneration;const current=readLocal(SERVER_ORDER_KEY);if(current)sgRemember(current);const refs=readLocal('sg-history-refs-v1')||[];const local=readLocal('sg-history-v1')||[];host.replaceChildren();const msg=document.createElement('p');msg.textContent=tr('Bestellungen werden geladen…','Загружаем заказы…');host.append(msg);let remote=[],failed=false;try{if(refs.length){const r=await fetch('/api/orders/history.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refs}),cache:'no-store'});if(!r.ok)throw Error('history');remote=(await r.json()).orders;}}catch{failed=true;}if(generation!==sgHistoryGeneration)return;host.replaceChildren();function text(parent,tag,value){const el=document.createElement(tag);el.textContent=value;parent.append(el);return el;}if(failed)text(host,'p',tr('Server nicht erreichbar. Lokal gespeicherte Bestellungen.','Сервер недоступен. Локальная история.'));const rows=[...remote.map(o=>({...o,server:true})),...local.filter(o=>!remote.some(r=>r.number===o.id.slice(-6)))];if(!rows.length)text(host,'p',tr('Noch keine Bestellungen.','Пока нет заказов.'));for(const o of rows){const card=document.createElement('article');card.className='sg-history-card';const status=o.server?(o.status==='delivered'?'done':o.status):o.status;const top=text(card,'div','');top.className='sg-history-top';text(top,'strong',tr('Bestellung #','Заказ № ')+(o.server?o.number:o.id.slice(-6)));const badge=text(top,'span',receiptStatus({status})+(status==='done'?' ✓':''));badge.className='sg-history-status';badge.dataset.status=status;const date=o.server?new Date(sgAbsolute(o.created_at)):new Date(o.date);if(!isNaN(date)){const d=date.toLocaleDateString('de-DE',{timeZone:'Europe/Berlin'});const t=date.toLocaleTimeString('de-DE',{timeZone:'Europe/Berlin',hour:'2-digit',minute:'2-digit'});text(card,'p',d+' · '+t+tr(' Uhr','')).className='sg-history-date';}const items=text(card,'div','');items.className='sg-history-items';for(const i of o.items){const item=text(items,'div',(o.server?i.quantity:i.qty)+' × '+(o.server?i.product_name:receiptItemName(i)));item.className='sg-history-item';const drink=i.drink;if(drink)text(item,'small',tr('Pommes frites','Картофель фри')+' · '+(drinkChoices.find(([id])=>id===drink)?.[1]||drink)).className='sg-history-drink';}const total=text(card,'div','');total.className='sg-history-total';text(total,'span',tr('Gesamt','Итого'));text(total,'strong',euro(o.server?o.total_cents/100:o.items.reduce((s,i)=>s+i.qty*i.price,0)));host.append(card);}}
